import twilio from "twilio";

if (!process.env.TWILIO_ACCOUNT_SID) {
  throw new Error("TWILIO_ACCOUNT_SID is missing from .env.local");
}
if (!process.env.TWILIO_AUTH_TOKEN) {
  throw new Error("TWILIO_AUTH_TOKEN is missing from .env.local");
}

export const client = twilio(
  process.env.TWILIO_ACCOUNT_SID,
  process.env.TWILIO_AUTH_TOKEN,
);

export const TWILIO_PHONE_NUMBER = process.env.TWILIO_PHONE_NUMBER ?? "";
export const TWILIO_VERIFY_SERVICE_SID = process.env.TWILIO_VERIFY_SERVICE_SID ?? "";

files.sms.ts:
"use server";

import { client, TWILIO_PHONE_NUMBER } from "./client";

export interface SendSmsParams {
  to: string;
  body: string;
  from?: string;
}

export interface SmsResult {
  sid: string;
  status: string;
  to: string;
  from: string;
}

export async function sendSms(params: SendSmsParams): Promise<SmsResult> {
  const message = await client.messages.create({
    to: params.to,
    from: params.from ?? TWILIO_PHONE_NUMBER,
    body: params.body,
  });

  return {
    sid: message.sid,
    status: message.status,
    to: message.to,
    from: message.from,
  };
}

files.voice.ts:
"use server";

import { client, TWILIO_PHONE_NUMBER } from "./client";

export interface MakeCallParams {
  to: string;
  from?: string;
  /** URL that Twilio will request for TwiML instructions when the call connects */
  webhookUrl: string;
  statusCallbackUrl?: string;
}

export interface CallResult {
  sid: string;
  status: string;
  to: string;
  from: string;
}

export async function makeCall(params: MakeCallParams): Promise<CallResult> {
  const call = await client.calls.create({
    to: params.to,
    from: params.from ?? TWILIO_PHONE_NUMBER,
    url: params.webhookUrl,
    statusCallback: params.statusCallbackUrl,
  });

  return {
    sid: call.sid,
    status: call.status,
    to: call.to,
    from: call.from,
  };
}

files.verify.ts:
"use server";

import { client, TWILIO_VERIFY_SERVICE_SID } from "./client";

export type VerifyChannel = "sms" | "call" | "email" | "whatsapp";

export interface VerificationResult {
  sid: string;
  status: string;
  to: string;
  channel: string;
}

export interface VerificationCheckResult {
  sid: string;
  status: "approved" | "pending" | "canceled";
  to: string;
  valid: boolean;
}

export async function sendVerificationCode(
  to: string,
  channel: VerifyChannel = "sms",
): Promise<VerificationResult> {
  if (!TWILIO_VERIFY_SERVICE_SID) {
    throw new Error("TWILIO_VERIFY_SERVICE_SID is missing from .env.local");
  }

  const verification = await client.verify.v2
    .services(TWILIO_VERIFY_SERVICE_SID)
    .verifications.create({ to, channel });

  return {
    sid: verification.sid,
    status: verification.status,
    to: verification.to,
    channel: verification.channel,
  };
}

export async function checkVerificationCode(
  to: string,
  code: string,
): Promise<VerificationCheckResult> {
  if (!TWILIO_VERIFY_SERVICE_SID) {
    throw new Error("TWILIO_VERIFY_SERVICE_SID is missing from .env.local");
  }

  const check = await client.verify.v2
    .services(TWILIO_VERIFY_SERVICE_SID)
    .verificationChecks.create({ to, code });

  return {
    sid: check.sid,
    status: check.status as "approved" | "pending" | "canceled",
    to: check.to,
    valid: check.valid,
  };
}

