import { headers } from "next/headers";
import twilio from "twilio";
import { MessagingResponse } from "twilio/lib/twiml/MessagingResponse";

export async function POST(req: Request) {
  const TWILIO_AUTH_TOKEN = process.env.TWILIO_AUTH_TOKEN;
  if (!TWILIO_AUTH_TOKEN) {
    console.error("[twilio sms webhook] TWILIO_AUTH_TOKEN is not set");
    return new Response("Server misconfiguration", { status: 500 });
  }

  const headersList = await headers();
  const signature = headersList.get("x-twilio-signature");
  if (!signature) {
    return new Response("Bad request", { status: 400 });
  }

  const url = req.url;
  const rawBody = await req.text();
  const params: Record<string, string> = {};
  new URLSearchParams(rawBody).forEach((value, key) => {
    params[key] = value;
  });

  const isValid = twilio.validateRequest(TWILIO_AUTH_TOKEN, signature, url, params);
  if (!isValid) {
    console.error("[twilio sms webhook] Invalid signature");
    return new Response("Unauthorized", { status: 401 });
  }

  const from = params["From"] ?? "";
  const body = params["Body"] ?? "";

  console.log(`[twilio sms webhook] Received from ${from}: ${body}`);

  // Build TwiML reply — customize this to send a response SMS
  const twiml = new MessagingResponse();
  // twiml.message("Thanks for your message!");

  return new Response(twiml.toString(), {
    status: 200,
    headers: { "Content-Type": "text/xml" },
  });
}

